ENDOFFILE"

/bin/bash -lc "cat > /bench/20260516-151352-two-turn-minmount-smoke/workspace/public/css/styles.css << 'ENDOFFILE'
/* Revenue Command Center — Stylesheet */
:root {
  --bg-primary: #080c14;
  --bg-card: #101624;
  --bg-card-hover: #161e30;
  --bg-input: #1a2035;
  --border: #1e2a3e;
  --border-active: #2d4a7a;
  --text-primary: #e4e8f0;
  --text-secondary: #8896b4;
  --text-muted: #556080;
  --accent: #4a8cff;
  --accent-glow: rgba(74, 140, 255, 0.15);
  --green: #34d399;
  --green-bg: rgba(52, 211, 153, 0.1);
  --amber: #fbbf24;
  --amber-bg: rgba(251, 191, 36, 0.1);
  --red: #f87171;
  --red-bg: rgba(248, 113, 113, 0.1);
  --critical: #ef4444;
  --critical-bg: rgba(239, 68, 68, 0.12);
  --radius: 6px;
  --radius-lg: 10px;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  --transition: 150ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* ---- Layout ---- */
.app-header {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}
.app-header h1 {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-primary);
}
.app-header .badge {
  font-size: 11px;
  font-weight: 600;
  background: var(--accent-glow);
  color: var(--accent);
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.04em;
}
.app-main {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px;
}

/* ---- Metrics Row ---- */
.metrics-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
  margin-bottom: 24px;
}
.metric-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px 18px;
  transition: border-color var(--transition);
}
.metric-card:hover { border-color: var(--border-active); }
.metric-card .metric-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}
.metric-card .metric-value {
  font-size: 24px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}
.metric-card .metric-sub {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}
.metric-card.warn { border-color: var(--amber); background: var(--amber-bg); }
.metric-card.danger { border-color: var(--red); background: var(--red-bg); }
.metric-card .metric-value.warn { color: var(--amber); }
.metric-card .metric-value.danger { color: var(--red); }

/* ---- Toolbar ---- */
.toolbar {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
  align-items: center;
}
.toolbar input[type=\"search\"] {
  flex: 1;
  min-width: 220px;
  max-width: 420px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 14px;
  font-size: 14px;
  color: var(--text-primary);
  font-family: var(--font);
  outline: none;
  transition: border-color var(--transition);
}
.toolbar input[type=\"search\"]:focus { border-color: var(--accent); }
.toolbar input[type=\"search\"]::placeholder { color: var(--text-muted); }
.toolbar select {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 13px;
  color: var(--text-primary);
  font-family: var(--font);
  outline: none;
  cursor: pointer;
}
.toolbar select:focus { border-color: var(--accent); }
.toolbar .filter-group {
  display: flex;
  gap: 6px;
}
.toolbar .filter-chip {
  font-size: 12px;
  font-weight: 500;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 5px 14px;
  cursor: pointer;
  color: var(--text-secondary);
  transition: all var(--transition);
  user-select: none;
}
.toolbar .filter-chip:hover { border-color: var(--border-active); color: var(--text-primary); }
.toolbar .filter-chip.active { background: var(--accent-glow); border-color: var(--accent); color: var(--accent); }
.toolbar .summary-text {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-muted);
}

/* ---- Account List ---- */
.account-list { display: flex; flex-direction: column; gap: 4px; }
.account-row {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition), background var(--transition);
}
.account-row:hover { background: var(--bg-card-hover); }
.account-row.expanded { border-color: var(--border-active); }

.account-summary {
  display: grid;
  grid-template-columns: 1.2fr 0.6fr 0.7fr 0.5fr 1fr;
  align-items: center;
  padding: 14px 18px;
  cursor: pointer;
  gap: 12px;
  font-size: 13px;
}
.account-summary .acct-name { font-weight: 600; color: var(--text-primary); }
.account-summary .acct-tier { font-size: 11px; color: var(--text-secondary); }
.account-summary .acct-arr { font-variant-numeric: tabular-nums; text-align: right; }
.account-summary .acct-score { text-align: center; }
.account-summary .risk-pills { display: flex; gap: 5px; flex-wrap: wrap; }
.risk-pill {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.risk-pill.renewals { background: var(--amber-bg); color: var(--amber); }
.risk-pill.billing { background: var(--red-bg); color: var(--red); }
.risk-pill.support { background: var(--amber-bg); color: var(--amber); }
.risk-pill.usage { background: var(--amber-bg); color: var(--amber); }
.risk-pill.incidents { background: var(--red-bg); color: var(--red); }

/* Health score bar */
.health-bar-wrap { width: 48px; height: 6px; background: var(--bg-input); border-radius: 3px; overflow: hidden; display: inline-block; }
.health-bar-fill { height: 100%; border-radius: 3px; transition: width 0.4s ease; }
.health-bar-fill.high { background: var(--green); }
.health-bar-fill.medium { background: var(--amber); }
.health-bar-fill.low { background: var(--red); }
.score-val { font-size: 11px; color: var(--text-muted); margin-left: 6px; font-variant-numeric: tabular-nums; }

/* ---- Detail Panel ---- */
.account-detail {
  display: none;
  border-top: 1px solid var(--border);
  padding: 18px 18px 20px;
  background: rgba(16, 22, 36, 0.6);
}
.account-detail.visible { display: block; }
.detail-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}
.detail-header h3 { font-size: 14px; font-weight: 600; }
.detail-header .risk-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 12px;
  text-transform: uppercase;
