}
.risk-badge.critical { background: var(--critical-bg); color: var(--critical); }
.risk-badge.high { background: var(--red-bg); color: var(--red); }
.risk-badge.medium { background: var(--amber-bg); color: var(--amber); }
.risk-badge.low { background: var(--green-bg); color: var(--green); }

.domain-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}
.domain-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
}
.domain-card h4 {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 8px;
}
.domain-card .domain-item {
  font-size: 12px;
  color: var(--text-secondary);
  padding: 3px 0;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.domain-card .domain-item .status-tag {
  font-size: 10px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 4px;
  white-space: nowrap;
}
.status-tag.at-risk, .status-tag.critical { background: var(--red-bg); color: var(--red); }
.status-tag.overdue { background: var(--red-bg); color: var(--red); }
.status-tag.open, .status-tag.investigating { background: var(--amber-bg); color: var(--amber); }
.status-tag.in-progress, .status-tag.pending { background: var(--amber-bg); color: var(--amber); }
.status-tag.healthy, .status-tag.paid, .status-tag.resolved { background: var(--green-bg); color: var(--green); }
.domain-card .empty-domain {
  font-size: 12px;
  color: var(--text-muted);
  font-style: italic;
}

/* ---- Action buttons ---- */
.btn {
  font-size: 12px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--bg-input);
  color: var(--text-secondary);
  cursor: pointer;
  font-family: var(--font);
  transition: all var(--transition);
}
.btn:hover { border-color: var(--border-active); color: var(--text-primary); }
.btn.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
.btn.primary:hover { filter: brightness(1.1); }

/* ---- Empty & Error States ---- */
.empty-state {
  padding: 60px 20px;
  text-align: center;
  color: var(--text-muted);
}
.empty-state .empty-icon { font-size: 48px; margin-bottom: 12px; opacity: 0.4; }
.empty-state p { font-size: 14px; }
.empty-state .empty-hint { font-size: 12px; margin-top: 4px; color: var(--text-muted); }

.error-banner {
