// Revenue Command Center — Application Controller

(function () {
  'use strict';

  // ---- State ----
  const state = {
    filters: { search: '', riskFilter: 'all', domainFilter: 'all' },
    expandedId: null,
    ready: false,
    error: null,
  };

  // ---- DOM refs ----
  const "'$metrics = document.getElementById('"'metrics-row');
  const "'$search = document.getElementById('"'search-input');
  const "'$riskFilter = document.getElementById('"'risk-filter');
  const "'$domainFilter = document.getElementById('"'domain-filter');
  const "'$filterChips = document.querySelectorAll('"'.filter-chip');
  const "'$accountList = document.getElementById('"'account-list');
  const "'$summary = document.getElementById('"'results-summary');
  const "'$errorContainer = document.getElementById('"'error-container');

  // ---- Render ----
  function refreshMetrics() {
    if ("'!$metrics) return;
    const m = DATA.getMetrics();
    $metrics.innerHTML = Components.renderMetricsRow(m);
  }

  function refreshAccountList() {
    if (!$accountList) return;
    let filtered;
    let errorMsg = null;

    try {
      filtered = Utils.filterAccounts(DATA.riskProfiles, DATA.accounts, state.filters);
    } catch (e) {
      errorMsg = e.message;
      filtered = [];
    }

    // Error banner
    if ($errorContainer) {
      if (state.error) {
        $errorContainer.innerHTML = Components.renderErrorState(state.error);
      } else if (errorMsg) {
        $errorContainer.innerHTML = Components.renderErrorState(errorMsg);
      } else {
        $errorContainer.innerHTML = '"'';
      }
    }

    if ("'!$accountList) return;

    if (filtered.length === 0) {
      $accountList.innerHTML = Components.renderEmptyState();
      if ($summary) $summary.textContent = '"'0 results';
      return;
    }

    if ("'$summary) $summary.textContent = filtered.length + '"' of ' + DATA.accounts.length + ' accounts';

    "'$accountList.innerHTML = filtered.map(p => {
      const acct = DATA.getAccountById(p.accountId);
      if (!acct) return '"'';
      return Components.renderAccountRow(acct, p, state.expandedId === acct.id);
    }).join('');

    // Attach expand listeners
    "'$accountList.querySelectorAll('"'.account-summary').forEach(el => {
      el.addEventListener('click', (e) => {
        const row = el.closest('.account-row');
        if ("'!row) return;
        const id = row.dataset.accountId;
        toggleDetail(id);
        e.stopPropagation();
      });
    });

    // Attach close-detail buttons
    $accountList.querySelectorAll('"'[data-action=\"close-detail\"]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = btn.dataset.id;
        closeDetail(id);
        e.stopPropagation();
      });
    });

    // Render already-expanded detail
